INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50211, 'Songofsongs 2:13', 'Songofsongs', 2, 13, 'د اينځر بوټو خپله وړومبۍ مېوه ونيوله، او د انګورو بوټو د خپلو غوټو خوشبو خوره کړله. راپاڅه، راشه، زما محبوبې، زما ښائسته محبوبې، راځه ما سره لاړه شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_13.mp3', '', 1761754199, 1761754199),
(50212, 'Songofsongs 2:14', 'Songofsongs', 2, 14, 'زما ګوګوشتکې په کمر کښې د ګټانو شاته خپل ځان پټ کړے دېنه. زۀ ستا مخ ليدل غواړمه، او ستا آواز اورېدل غواړمه. ځکه چې ستا آواز خوږ دېنه، او ستا مخ ښائسته دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_14.mp3', '', 1761754199, 1761754199),
(50213, 'Songofsongs 2:15', 'Songofsongs', 2, 15, 'لومبړې ونيسه، وړې لومبړې ونيسه، هسې نه چې هغوئ د انګورو باغ تباه کړينه، ځکه چې زمونږ د انګور بوټو غوټۍ نيولې دينه.“ محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_15.mp3', '', 1761754199, 1761754199),
(50214, 'Songofsongs 2:16', 'Songofsongs', 2, 16, 'جانان زما او زۀ د جانان يمه، هغه چې د لاله په ګلونو کښې مزې کوينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_16.mp3', '', 1761754199, 1761754199),
(50215, 'Songofsongs 2:17', 'Songofsongs', 2, 17, 'د سحر رڼا نه وړاندې زما جانانه، چې شپه په ختمېدو شى، ما نه لاړ شه جانانه، لکه د هوسۍ او يا د تکړه هوسۍ په شان په کاڼيزه غرونو باندې ما نه په ټوپونو او مستۍ سره لاړ شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_17.mp3', '', 1761754199, 1761754199),
(50216, 'Ruth 4:1', 'Ruth', 4, 1, 'بوعز د غونډې ځای ته چې د ښار د دروازې سره ؤ، لاړ او هلته کښېناست. کله چې د الیملک زیات نژدې خپلوان راغی، نو بوعز هغه ته بلنه ورکړه چې راشي او کښېني، نو هغه همداسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_1.mp3', '', 1761754199, 1761754199),
(50217, 'Ruth 4:2', 'Ruth', 4, 2, 'بیا بوعز د ښار لسو مشرانو ته بلنه ورکړه چې په هغه ځای کې کښېني او هغوی همداسې وکړل. وروسته له دې چې هغوی کښېناستل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_2.mp3', '', 1761754199, 1761754199),
(50218, 'Ruth 4:3', 'Ruth', 4, 3, 'بوعز خپل خپلوان ته وویل: «اوس چې نعومي د موآب څخه بېرته راغلې، هغه غواړي چې هغه پټی چې زمونږ د خپلوان الیملک ملکیت ؤ، خرڅ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_3.mp3', '', 1761754199, 1761754199),
(50219, 'Ruth 4:4', 'Ruth', 4, 4, 'زه تاته دا ځکه وایم چې ته د هغه د ټولو نه نژدې خپلوان یې او ته دا حق لرې چې دا ملکیت واخلې، که چېرې ته غواړې کولای شې چې همدا اوس یې واخلې. دا لس مشران او دا نور چې دلته ناست دي، دا به شاهدان وي. خو که چېرې ته دا ملکیت نه غواړې بیا ماته ووایه، ځکه ستا نه وروسته بیا زما حق دی.» دې سړي په ځواب کې وویل: «زه به یې واخلم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_4.mp3', '', 1761754199, 1761754199),
(50220, 'Ruth 4:5', 'Ruth', 4, 5, 'بوعز وویل: «ډېره ښه ده، خو که چېرې ته دا پټی د نعومي نه اخلې، بیا به د موآبي کونډې روت سره واده هم کوې، ترڅو پټی بېرته د هغې د مړ شوي مېړه کورنۍ کې پاتې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_5.mp3', '', 1761754199, 1761754199),
(50221, 'Ruth 4:6', 'Ruth', 4, 6, 'سړي په ځواب کې وویل: «که چېرې داسې خبره وي، بیا زه نه غواړم چې دا ملکیت واخلم، ځکه چې هغه به زما خپل ملکیت کې څه ستونزه راپیدا کړي. ته یې په خپله واخله، زه یې نه شم اخیستلی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_6.mp3', '', 1761754199, 1761754199),
(50222, 'Ruth 4:7', 'Ruth', 4, 7, 'په هغو ورځو کې د ملکیت د خرڅولو یا بدلولو او راکړې ورکړې د موضوع د حل دپاره دا رواج ؤ چې خرڅوونکي خپله څپلۍ ویستله او اخیستونکي ته به یې ورکوله. په دې ډول به اسراییلیانو وښودله چې خبره حل شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_7.mp3', '', 1761754199, 1761754199),
(50223, 'Ruth 4:8', 'Ruth', 4, 8, 'نو وروسته له دې چې سړي موافقه وکړه چې بوعز پرېږدي چې دا ملکیت واخلي، هغه خپله څپلۍ وویستله او بوعز ته یې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_8.mp3', '', 1761754199, 1761754199),
(50224, 'Ruth 4:9', 'Ruth', 4, 9, 'نو بیا بوعز مشرانو او نورو حاضرو کسانو ته وویل: «نن تاسو ټول د دې خبرې شاهدان یئ چې ما د نعومي څخه هغه ملکیت واخیست چې د الیملک او د هغه د دوو زامنو په نوم ؤ، چې کلیون او محلون نومېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_9.mp3', '', 1761754199, 1761754199),
(50225, 'Ruth 4:10', 'Ruth', 4, 10, 'برسېره پردې تاسو د دې خبرې شاهدان یئ چې زه به روت سره چې د محلون کونډه ده، واده وکړم. په دې ډول به دا ملکیت د محلون د کورنۍ په نوم وساتل شي او د هغه نوم به په خپلو خلکو او خپل ښار کې په یاد پاتې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_10.mp3', '', 1761754199, 1761754199),
(50226, 'Ruth 4:11', 'Ruth', 4, 11, 'د ښار مشرانو او نورو خلکو چې هلته وو، وویل: «مونږ د دې خبرې شاهدان یو او مونږ دعا کوو چې څښتن دې ستا ښځې ته ډېر اولادونه ورکړي، څنګه یې چې د یعقوب ښځو راحیل او لیه ته ورکړي وو. ته دې د افراتې په طایفه کې شتمن او د بیت لحم په ښار کې مشهور سړی شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_11.mp3', '', 1761754199, 1761754199),
(50227, 'Ruth 4:12', 'Ruth', 4, 12, 'د دې ځوانې ښځې څخه چې ستا اولادونه پیدا شي، هغوی دې ستا کورنۍ د فارص د کورنۍ په شان مشهوره کړي چې د تامار او یهودا زوی ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_12.mp3', '', 1761754199, 1761754199),
(50228, 'Ruth 4:13', 'Ruth', 4, 13, 'نو بوعز روت خپل کور ته د خپلې مېرمنې په توګه بوتله. څښتن هغې ته برکت ورکړ، هغه امیدواره شوه او زوی یې پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_13.mp3', '', 1761754199, 1761754199),
(50229, 'Ruth 4:14', 'Ruth', 4, 14, 'د هغه د زېږېدلو څخه وروسته، ښځو نعومي ته وویل: «د څښتن ستاینه وکړه. نن هغه تاته لمسی درکړی چې په تا پام وکړي. مونږ دعا کوو چې دا هلک دې لوی شي او په اسراییلو کې دې نامتو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_14.mp3', '', 1761754199, 1761754199),
(50230, 'Ruth 4:15', 'Ruth', 4, 15, 'ته خپلې انږور ته ګرانه یې او تا سره یې د اووه زامنو څخه ډېر ښه کړي دي. اوس یې تاته لمسی هم درکړ چې هغه به تاته نوی ژوند درکړي او هغه به ستا په اخر عمر کې ستا ساتنه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_15.mp3', '', 1761754199, 1761754199),
(50231, 'Ruth 4:16', 'Ruth', 4, 16, 'نعومي ماشوم واخیست، په غېږ کې یې ونیوه او د هغه ساتنه یې وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_16.mp3', '', 1761754199, 1761754199),
(50232, 'Ruth 4:17', 'Ruth', 4, 17, 'ګاونډیو ښځو د هغه نوم عوبید کېښود او ویل به یې چې د نعومي هلک پیدا شوی دی. کله چې عوبید لوی شو د هغه یو زوی پیدا شو چې یسي نومېده او یسي بیا وروسته د داود پلار شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth4_verse_17.mp3', '', 1761754199, 1761754199),
(50233, 'Genesis 23:1', 'Genesis', 23, 1, 'ساره یوسلو اووه ویشت کاله ژوندۍ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_1.mp3', '', 1761754199, 1761754199),
(50234, 'Genesis 23:2', 'Genesis', 23, 2, 'هغه په قریت‌اربع (حبرون) کې چې د کنعان په هېواد کې دی، مړه شوه او ابراهیم د ساره دپاره غمجن شو او په هغې پسې یې وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_2.mp3', '', 1761754199, 1761754199),
(50235, 'Genesis 23:3', 'Genesis', 23, 3, 'بیا ابراهیم د خپلې ښځې د مړي له څنګه پاڅېده او حیتیانو ته ورغی او ویې ویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_3.mp3', '', 1761754199, 1761754199),
(50236, 'Genesis 23:4', 'Genesis', 23, 4, '«زه دلته ستاسو په منځ کې پردی او مسافر یم. یو څه ځمکه په ما باندې خرڅه کړئ، ترڅو خپله ښځه په کې ښخه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_4.mp3', '', 1761754199, 1761754199),
(50237, 'Genesis 23:5', 'Genesis', 23, 5, 'هغوی ځواب ورکړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_5.mp3', '', 1761754199, 1761754199),
(50238, 'Genesis 23:6', 'Genesis', 23, 6, '«باداره، زمونږ خبره واوره. مونږ تاته د یو قوي مشر په سترګه ګورو. زمونږ په یوه ډېره ښه هدیره کې خپل مړی ښخ کړه. مونږ هر یو به خوشحاله شو چې د قبر دپاره ځای درکړو، ترڅو خپله ښځه په کې ښخه کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_6.mp3', '', 1761754199, 1761754199),
(50239, 'Genesis 23:7', 'Genesis', 23, 7, 'نو ابراهیم پاڅېد او د درناوي په خاطر یې هغوی ته خپل سر ټیټ کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_7.mp3', '', 1761754199, 1761754199),
(50240, 'Genesis 23:8', 'Genesis', 23, 8, 'او ورته ویې ویل: «که ستاسو خوښه وي، نو پرېږدئ چې خپل مړی ښخ کړم. تاسو زما په خاطر د صوحار د زوی عفرون څخه وغواړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_8.mp3', '', 1761754199, 1761754199),
(50241, 'Genesis 23:9', 'Genesis', 23, 9, 'چې د مکفیلې سمڅه چې د هغه جایداد دی او د هغه د پټي سرته پرته ده، په پوره بیه په ما باندې خرڅه کړي. دا به ستاسو په منځ کې زمونږ هدیره وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_9.mp3', '', 1761754199, 1761754199),
(50242, 'Genesis 23:10', 'Genesis', 23, 10, 'عفرون په خپله د نورو حیتیانو سره د ښار په دروازه کې د غونډې په ځای کې ناست ؤ. هغه ابراهیم ته د ټولو حیتیانو په مخکې چې هلته حاضر وو ځواب ورکړ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_10.mp3', '', 1761754199, 1761754199),
(50243, 'Genesis 23:11', 'Genesis', 23, 11, 'هغه وویل: «نه، زما باداره! زما خبره واوره. زه دا پټی او هغه سمڅه چې په هغه کې ده د خپل قوم په مخکې تاته درکوم، خپل مړی دې په کې ښخ کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_11.mp3', '', 1761754199, 1761754199),
(50244, 'Genesis 23:12', 'Genesis', 23, 12, 'ابراهیم یوځل بیا د حیتیانو په وړاندې د درناوي په خاطر سر ټیټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_12.mp3', '', 1761754199, 1761754199),
(50245, 'Genesis 23:13', 'Genesis', 23, 13, 'هغه د ټولو په مخکې عفرون ته وویل: «زما خبره واوره. که چېرې ستا رضا وي، زه به د پټي بیه درکړم. دا زما له خوا قبوله کړه، ترڅو خپل مړی هلته ښخ کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_13.mp3', '', 1761754199, 1761754199),
(50246, 'Genesis 23:14', 'Genesis', 23, 14, 'عفرون ځواب ورکړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_14.mp3', '', 1761754199, 1761754199),
(50247, 'Genesis 23:15', 'Genesis', 23, 15, '«ای زما باداره، زما خبره واوره. د دې ځمکې بیه څلور سوه د سپینو زرو سکې دي، خو دا زما او ستا ترمنځ هېڅ شی نه دی. خپل مړی دې په کې ښخ کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_15.mp3', '', 1761754199, 1761754199),
(50248, 'Genesis 23:16', 'Genesis', 23, 16, 'نو ابراهیم د عفرون خبره قبوله کړه او هغه بیه چې عفرون د حیتیانو په مخکې ټاکلې وه، یعنې څلور سوه د سپینو زرو سکې عفرون ته وتللې. دا د هغه وزن سره سم وو چې په هغه وخت کې یې د سوداګرانو په منځ کې رواج درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_16.mp3', '', 1761754199, 1761754199),
(50249, 'Genesis 23:17', 'Genesis', 23, 17, 'په دې ډول د عفرون جایداد چې په مکفیله کې د ممري په لمرخاته کې ؤ، هغه د ابراهیم شو. په هغه کې پټی او هغه سمڅه چې په هغه پټي کې وه او د هغې ځمکې شاوخوا ټولې ونې شاملې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_17.mp3', '', 1761754199, 1761754199),
(50250, 'Genesis 23:18', 'Genesis', 23, 18, 'دا ځمکه د ټولو حیتیانو په مخکې چې په هغې غونډې کې حاضر وو، د ابراهیم د جایداد په توګه وپېژندل شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_18.mp3', '', 1761754199, 1761754199),
(50251, 'Genesis 23:19', 'Genesis', 23, 19, 'نو ابراهیم خپله ښځه ساره ممري ته نژدې چې په حبرون کې ده، د کنعان په خاوره کې د مکفیله په سمڅه کې ښخه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_19.mp3', '', 1761754199, 1761754199),
(50252, 'Genesis 23:20', 'Genesis', 23, 20, 'نو هغه پټی او سمڅه چې په هغې کې وه، د حیتیانو له خوا ابراهیم ته د هدیرې دپاره د هغه د ملکیت په توګه ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis23_verse_20.mp3', '', 1761754199, 1761754199),
(50253, 'Genesis 14:1', 'Genesis', 14, 1, 'په هغه وخت کې د شنعار پاچا امرافل، د الاسار پاچا اریوک، د عیلام پاچا کدرلاعمر او د قوییم پاچا تدعال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_1.mp3', '', 1761754199, 1761754199),
(50254, 'Genesis 14:2', 'Genesis', 14, 2, 'لاړل چې د نورو پنځو پاچاهانو یعنې د سدوم د پاچا بارع، د عمورې د پاچا برشاع، د ادمه د پاچا شنعاب، د زبوییم د پاچا شمیبر او د بالع د پاچا سره (بالع هماغه صوغر دی) جنګ وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_2.mp3', '', 1761754199, 1761754199),
(50255, 'Genesis 14:3', 'Genesis', 14, 3, 'دغو پنځو پاچاهانو خپل ځواکونه د سدیم په دره کې چې اوس د مړې بحیرې په نوم یادیږي سره یوځای کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_3.mp3', '', 1761754199, 1761754199),
(50256, 'Genesis 14:4', 'Genesis', 14, 4, 'هغوی دولس کاله د کدرلاعمر تر لاس لاندې وو، خو په دیارلسم کال هغوی یاغي شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_4.mp3', '', 1761754199, 1761754199),
(50257, 'Genesis 14:5', 'Genesis', 14, 5, 'په څوارلسم کال کدرلاعمر د هغو پاچاهانو سره چې د ده سره ملګري شوي وو، لاړ او رفاییانو ته یې په عشتروت قرنین، زوزیانو ته یې په هام او ایمیانو ته یې په شاوه قیریتایم کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_5.mp3', '', 1761754199, 1761754199),
(50258, 'Genesis 14:6', 'Genesis', 14, 6, 'او حوریانو ته یې د ادوم په غرنۍ سیمه کې تر ایل فاران پورې چې دښتې ته نژدې دی، ماتې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_6.mp3', '', 1761754199, 1761754199),
(50259, 'Genesis 14:7', 'Genesis', 14, 7, 'بیا هغوی بېرته راوګرځېدل او عین مشفاط ته چې وروسته د قادش په نوم یاد شو، راغلل او د عمالیقیانو ټوله خاوره یې فتح کړه او اموریانو ته یې چې په حززون تامار کې اوسېدل، ماتې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_7.mp3', '', 1761754199, 1761754199),
(50260, 'Genesis 14:8', 'Genesis', 14, 8, 'په هغه وخت کې د سدوم، عموره، ادمه، زبوییم او د بالع (صوغر) پاچاهان ووتل او د سدیم په دره کې یې خپلې جنګي لیکې جوړې کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_8.mp3', '', 1761754199, 1761754199),
(50261, 'Genesis 14:9', 'Genesis', 14, 9, 'ترڅو د عیلام د پاچا کدرلاعمر، د قوییم د پاچا تدعال، د شنعار د پاچا امرافل او د الاسار د پاچا اریوک په وړاندې جنګ وکړي، یعنې څلور پاچاهان د پنځو په وړاندې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_9.mp3', '', 1761754199, 1761754199),
(50262, 'Genesis 14:10', 'Genesis', 14, 10, 'د سدیم په دره کې د قیر ډېرې کندې وې. کله چې د سدوم او عمورې پاچاهان د جګړې څخه وتښتېدل، هغوی په دې کندو کې وغورځېدل او پاتې پاچاهان غرونو ته وتښتېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_10.mp3', '', 1761754199, 1761754199),
(50263, 'Genesis 14:11', 'Genesis', 14, 11, 'نو څلورو پاچاهانو د سدوم او عمورې ټول شیان چې په هغو کې د هغوی خواړه هم شامل وو، واخیستل او لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_11.mp3', '', 1761754199, 1761754199),
(50264, 'Genesis 14:12', 'Genesis', 14, 12, 'هغوی د ابرام وراره لوط هم د هغه د ټول مال او جایداد سره د ځان سره یووړ، ځکه چې هغه په سدوم کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_12.mp3', '', 1761754199, 1761754199),
(50265, 'Genesis 14:13', 'Genesis', 14, 13, 'یو کس چې د هغو څخه تښتېدلی ؤ، عبراني ابرام ته خبر ورکړ. په دې وخت کې ابرام هغو لویو ونو ته نژدې چې د اموري ممري پورې یې اړه درلودله اوسېده. ممری او د هغه ورونه اشکول او عانر ټول د ابرام سره ملګري وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_13.mp3', '', 1761754199, 1761754199),
(50266, 'Genesis 14:14', 'Genesis', 14, 14, 'کله چې ابرام خبر شو چې د هغه وراره نیول شوی دی، نو هغه خپل درې سوه اتلس جنګي کسان راوغوښتل او تر دان پورې په هغو څلورو پاچاهانو پسې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_14.mp3', '', 1761754199, 1761754199),
(50267, 'Genesis 14:15', 'Genesis', 14, 15, 'د شپې ابرام خپل کسان سره ووېشل چې په دښمن باندې حمله وکړي او هغوی ته یې ماتې ورکړه او تر حوبې پورې چې د دمشق په شمال کې ده، ورپسې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_15.mp3', '', 1761754199, 1761754199),
(50268, 'Genesis 14:16', 'Genesis', 14, 16, 'ابرام هغه ټول سامان چې هغوی لوټ کړی ؤ او د ځان سره یې وړی ؤ، بېرته راوګرځاوه. همدارنګه هغه خپل وراره لوط د هغه د شتمنۍ سره او ښځې او نور بندیان د ځان سره بېرته راوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_16.mp3', '', 1761754199, 1761754199),
(50269, 'Genesis 14:17', 'Genesis', 14, 17, 'کله چې ابرام کدرلاعمر او د هغه سره ملګرو پاچاهانو ته ماتې ورکړه او بېرته راستون شو، د سدوم پاچا د شاوه د درې پورې (چې د پاچا د درې په نوم هم یادیږي) د هغه د لیدلو دپاره راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_17.mp3', '', 1761754199, 1761754199),
(50270, 'Genesis 14:18', 'Genesis', 14, 18, 'ملک‌صدق چې د سالیم پاچا او د خدای تعالی کاهن ؤ، د ابرام دپاره ډوډۍ او شراب راوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_18.mp3', '', 1761754199, 1761754199),
(50271, 'Genesis 14:19', 'Genesis', 14, 19, 'هغه ابرام ته برکت ورکړ او ویې ویل: «خدای تعالی چې د ځمکې او اسمانونو پیدا کوونکی دی، تاته برکت درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_19.mp3', '', 1761754199, 1761754199),
(50272, 'Genesis 14:20', 'Genesis', 14, 20, 'د خدای تعالی ثنا دې وي چې ستا دښمنان یې تاته تسلیم کړل.» نو ابرام ملک‌صدق ته د هغو شیانو چې هغه بېرته اخیستي وو، لسمه برخه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_20.mp3', '', 1761754199, 1761754199),
(50273, 'Genesis 14:21', 'Genesis', 14, 21, 'د سدوم پاچا ابرام ته وویل: «زما ټول خلک بېرته ماته راکړه او شیان دې خپل ځان ته وساته.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_21.mp3', '', 1761754199, 1761754199),
(50274, 'Genesis 14:22', 'Genesis', 14, 22, 'ابرام ځواب ورکړ: «زه د څښتن یعنې خدای تعالی په حضور کې چې د ځمکې او اسمانونو پیدا کوونکی دی، په کلکه قسم خورم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_22.mp3', '', 1761754199, 1761754199),
(50275, 'Genesis 14:23', 'Genesis', 14, 23, 'چې زه به ستا د شیانو څخه هېڅ شی حتی یو تار یا د څپلۍ تسمه هم وانخلم، هسې نه چې بیا ووایې چې ابرام ما شتمن کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_23.mp3', '', 1761754199, 1761754199),
(50276, 'Genesis 14:24', 'Genesis', 14, 24, 'زه به د خپل ځان دپاره هېڅ شی وانخلم. یوازېنی شی چې زه به یې قبول کړم دا هغه څه دي چې زما خلکو خوړلي دي او د هغه چا برخه چې زما سره تللي وو یعنې د عانر، اشکول او ممري برخه هغوی ته ورکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis14_verse_24.mp3', '', 1761754199, 1761754199),
(50277, 'Esther 5:1', 'Esther', 5, 1, 'د روژې په درېمه ورځ استر خپل شاهانه کالي واغوستل، بیا لاړه او د ماڼۍ په دننه دربار کې د پاچا د شاهي تخت کوټې ته مخامخ ودرېدله. پاچا دننه ؤ او په همدې کوټې کې دروازې ته مخامخ په خپل تخت باندې ناست ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_1.mp3', '', 1761754199, 1761754199),
(50278, 'Esther 5:2', 'Esther', 5, 2, 'کله چې هغه ولیدل چې ملکه استر په حوېلۍ کې ولاړه ده، پاچا په هغې مهربانه شو او خپله د سرو زرو امسا چې د هغه په لاس کې وه، د هغې خواته وراوږده کړه. نو استر ورنژدې شوه او د هغه د امسا څوکې ته یې لاس وروړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_2.mp3', '', 1761754199, 1761754199),
(50279, 'Esther 5:3', 'Esther', 5, 3, 'پاچا پوښتنه وکړه: «ای ملکې استر، څه خبره ده؟ ووایه څه شی غواړې، حتی که هغه زما نیمه امپراتوري هم وي تاته به درکړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_3.mp3', '', 1761754199, 1761754199),
(50280, 'Esther 5:4', 'Esther', 5, 4, 'استر ځواب ورکړ: «که ستاسو اعلیحضرت خوښه وي، نن تاسو او هامان هغې مېلمستیا ته راشئ چې ستاسو دپاره مې تیاره کړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_4.mp3', '', 1761754199, 1761754199),
(50281, 'Esther 5:5', 'Esther', 5, 5, 'پاچا وویل: «هامان سمدلاسه راولئ، ترڅو د استر غوښتنه پوره شي.» نو پاچا او هامان د استر مېلمستیا ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_5.mp3', '', 1761754199, 1761754199),
(50282, 'Esther 5:6', 'Esther', 5, 6, 'د شرابو د څښلو په وخت کې پاچا د استر څخه پوښتنه وکړه: «ماته ووایه چې ته څه غواړې هغه به درته درکړل شي. ستا غوښتنه څه ده؟ که ته وغواړې، زه به حتی نیمه امپراتوري هم درک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_6.mp3', '', 1761754199, 1761754199),
(50283, 'Esther 5:7', 'Esther', 5, 7, 'استر ځواب ورکړ: «زما هیله او غوښتنه دا ده:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_7.mp3', '', 1761754199, 1761754199),
(50284, 'Esther 5:8', 'Esther', 5, 8, 'که چېرې تاسو اعلیحضرت زما سره خوشحاله یئ، مهرباني وکړئ زما غوښتنه ومنئ، نو زه غواړم چې سبا تاسو او هامان هغې بلې مېلمستیا ته راشئ چې زه یې ستاسو دپاره تیاروم. هغه وخت به تاسو ته ووایم چې زه څه غواړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_8.mp3', '', 1761754199, 1761754199),
(50285, 'Esther 5:9', 'Esther', 5, 9, 'کله چې هامان د مېلمستیا څخه ووت، هغه د زړه له کومي خوشحاله ؤ. خو کله چې هغه مردخای د ماڼۍ په دروازه کې ولیده، مردخای ورته د درناوي په خاطر ونه درېد او نه ورڅخه ووېرېده، نو هامان په هغه باندې ډېر په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_9.mp3', '', 1761754199, 1761754199),
(50286, 'Esther 5:10', 'Esther', 5, 10, 'خو هامان خپل ځان کنترول کړ او خپل کور ته لاړ. نو بیا هغه خپل ملګري خپل کور ته راوغوښتل او د خپلې ښځې زرش نه یې هم وغوښتل چې د دوی په غونډه کې ګډون وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_10.mp3', '', 1761754199, 1761754199),
(50287, 'Esther 5:11', 'Esther', 5, 11, 'نو هامان ورته لافې ووهلې چې هغه څومره شتمن دی، څومره ډېر زامن یې دي، پاچا هغه ته څومره لوړ مقام ورکړی دی او دا چې هغه یې د پاچا د نورو ټولو مامورینو نه لوړ کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_11.mp3', '', 1761754199, 1761754199),
(50288, 'Esther 5:12', 'Esther', 5, 12, 'هامان زیاته کړه: «حتی ملکې استر پرته له پاچا او ما هېڅوک هغې مېلمستیا ته چې هغې تیاره کړې وه، نه دی غوښتی. همدارنګه هغې د سبا دپاره هم زه او هم پاچا د مېلمستیا دپاره غوښتي یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_12.mp3', '', 1761754199, 1761754199),
(50289, 'Esther 5:13', 'Esther', 5, 13, 'خو ترڅو چې زه مردخای یهودي وینم چې د ماڼۍ په دروازه کې ناست دی دا ټول شیان زما دپاره هېڅ ارزښت نه لري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_13.mp3', '', 1761754199, 1761754199),
(50290, 'Esther 5:14', 'Esther', 5, 14, 'د هغه ښځې زرش او ټولو ملګرو یې هغه ته وویل: «د درویشت مترو په لوړوالي یو دار جوړ کړه او سبا سهار د پاچا څخه وغواړه چې مردخای په هغه باندې ځوړند شي. بیا کولای شې چې په خوشحالۍ سره مېلمستیا ته لاړ شې.» دغه نظر د هامان خوښ شو او امر یې وکړ چې دار دې جوړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther5_verse_14.mp3', '', 1761754199, 1761754199),
(50291, 'Psalms 89:1', 'Psalms', 89, 1, 'ای څښتنه، زه به تل ستا د تلپاتې مینې وایمه سندره په خپله خوله ټولو نسلونو ته به ستا وفاداري بیان کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_1.mp3', '', 1761754199, 1761754199),
(50292, 'Psalms 89:2', 'Psalms', 89, 2, 'ما ویل چې ستا مینه به شي پاتې تل دپاره وفاداري به دې وي ټینګه اسمانونو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_2.mp3', '', 1761754199, 1761754199),
(50293, 'Psalms 89:3', 'Psalms', 89, 3, 'وویل تا چې ما لوظ کړی دی داود سره چې ما خوښ کړی او خپل خادم داود سره مې کړی دا قسم دی:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_3.mp3', '', 1761754199, 1761754199),
(50294, 'Psalms 89:4', 'Psalms', 89, 4, '«اولاده ستا به کوي پاچاهي تل ستا پاچاهي به د یو نسل نه بل نسله پورې ټینګه ساتم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_4.mp3', '', 1761754199, 1761754199),
(50295, 'Psalms 89:5', 'Psalms', 89, 5, 'څښتنه، ستا عجیب کارونه اسمانونه ستایي د فرښتو ډله دې ستایي وفا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_5.mp3', '', 1761754199, 1761754199),
(50296, 'Psalms 89:6', 'Psalms', 89, 6, 'ای څښتنه، اسمانونو کې څوک نشته ستا په شان برابر نه دی هېڅ اسماني مخلوق د ستا سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_6.mp3', '', 1761754199, 1761754199),
(50297, 'Psalms 89:7', 'Psalms', 89, 7, 'د فرښتو غونډه کې ډېر زیات هیبتناک یې ته د هغو ټولو نه چې ستا په شاوخوا کې دي ته یې ډېر لوی او وېروونکی یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_7.mp3', '', 1761754199, 1761754199),
(50298, 'Psalms 89:8', 'Psalms', 89, 8, 'ای مطلق قادر څښتنه خدایه هېڅوک نه دی زورور د ستا په شان څښتنه، ته یې وفادار ټولو کارونو کې دې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_8.mp3', '', 1761754199, 1761754199),
(50299, 'Psalms 89:9', 'Psalms', 89, 9, 'ته حکومت کوې غړمبېدونکي دریاب باندې چې شي راپورته د هغه څپې اراموې یې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_9.mp3', '', 1761754199, 1761754199),
(50300, 'Psalms 89:10', 'Psalms', 89, 10, 'ټوټې ټوټې دې کړه بلا د دریاب هم دې مړه کړه هغه په قوي مټو تار په تار دې دښمنان کړل خپل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_10.mp3', '', 1761754199, 1761754199),
(50301, 'Psalms 89:11', 'Psalms', 89, 11, 'دي اسمانونه ستا هم ځمکه د ستا تا جوړه کړې نړۍ او هغې کې ټول شیان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_11.mp3', '', 1761754199, 1761754199),
(50302, 'Psalms 89:12', 'Psalms', 89, 12, 'تا پیدا کړي دي شمال او جنوب دواړه د تابور او حرمون غرونه په خوشحالۍ سره ستا نوم ستایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_12.mp3', '', 1761754199, 1761754199),
(50303, 'Psalms 89:13', 'Psalms', 89, 13, 'ستا مټ ځواکمن دی! زورور دی ستا لاس ښي لاس برلاسی دی ستا!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_13.mp3', '', 1761754199, 1761754199),
(50304, 'Psalms 89:14', 'Psalms', 89, 14, 'ستا د شاهۍ بنیاد دی پروت په عدالت او په انصاف باندې تلپاتې مینه او وفا د ستا په مخکې درومي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_14.mp3', '', 1761754199, 1761754199),
(50305, 'Psalms 89:15', 'Psalms', 89, 15, 'هغه خلک بختور دي چې عبادت کوي د ستا د خوشحالۍ په چیغو چې تېروي ژوندون رڼا کې د احسان د ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_15.mp3', '', 1761754199, 1761754199),
(50306, 'Psalms 89:16', 'Psalms', 89, 16, 'هغوی کوي خوشحالي ستا په خاطر ټوله ورځ ستا د نېکۍ په خاطر د ستا ستاینه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_16.mp3', '', 1761754199, 1761754199),
(50307, 'Psalms 89:17', 'Psalms', 89, 17, 'ته په خپله یې د دوی جلال او قوت راکوې مونږ ته بری په خپل احسان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_17.mp3', '', 1761754199, 1761754199),
(50308, 'Psalms 89:18', 'Psalms', 89, 18, 'څښتن زمونږه سپر یعنې پاچا دی غوره کړی سپېڅلي خدای د اسراییلو مونږ ته خپل پاچا راکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_18.mp3', '', 1761754199, 1761754199),
(50309, 'Psalms 89:19', 'Psalms', 89, 19, 'تا ډېر پخوا خپلو وفادارو خادمانو ته رویا کې ویلي وو: «یو جنګیالي سره مې مرسته کړې او غوره کړی مې دی د قوم څخه او سرلوړی کړی مې دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_19.mp3', '', 1761754199, 1761754199),
(50310, 'Psalms 89:20', 'Psalms', 89, 20, 'ما خپل خدمتګار داود موندلی دی په خپلو سپېڅلو تېلو مې غوړ کړی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_20.mp3', '', 1761754199, 1761754199);